const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types=['Орон сууц','Хаус / Амьны орон сууц','Оффис / Үйлчилгээ','Газар түрээс','Богино хугацааны түрээс'],areas=['Сүхбаатар','Чингэлтэй','Баянгол','Баянзүрх','Хан-Уул','Сонгинохайрхан','Налайх','Багануур'];
const pictures=['photo-1600210492486-724fe5c67fb0','photo-1600607687920-4e2a09cf159d','photo-1522708323590-d24dbb6b0267','photo-1600566753086-00f18fb6b3ea','photo-1600047509807-ba8f99d2cdde','photo-1560448204-e02f11c3d0e2','photo-1484154218962-a197022b5858','photo-1560185007-c5ca9d2c014d'];
