const homes=Array.from({length:24},(_,i)=>({id:59377690+i,type:i%5,area:areas[i%8],currency:'MNT',price:i%7===0?[180000000,250000000,320000000][Math.floor(i/7)%3]:[1250000,1500000,1000000,2000000,750000,2500000,1750000,2250000][i%8],deposit:i%7===0?0:[1250000,1500000,1000000,2000000,750000,2500000,1750000,2250000][i%8],size:[24.16,34.74,23.45,45,16,42.97,28,33.65][i%8],floor:i%14+1,parking:i%3!==0,elevator:i%2===0,pet:i%4===0,year:2017+i%8,deal:i%7===0?'sale':'rent',name:['Сүхбаатар Резиденс','Чингэлтэй Апартмент','Баянгол Хотхон','Баянзүрх Резиденс','Хан-Уул Гарден','Сонгинохайрхан Хотхон','Налайх Парк','Багануур Резиденс'][i%8],desc:['Гэрэл сайтай, бүрэн тавилгатай тухтай орон зай','Автобусны буудлаас 5 минут, тохилог цэвэрхэн байр','Өргөн цонхтой, нүүхэд бэлэн орон сууц','Тайван хороолол, тав тухтай амьдрал'][i%4]}));
let saved=JSON.parse(localStorage.getItem('mn-saved')||'[]'),recent=JSON.parse(localStorage.getItem('mn-recent')||'[]'),filter=defaultFilter(),category=-1,query='',favTab=0,saleTab=0,zoom=1,sort='new',activeTag=0;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function save(id,e){e?.stopPropagation();saved=saved.includes(id)?saved.filter(n=>n!==id):[...saved,id];localStorage.setItem('mn-saved',JSON.stringify(saved));document.querySelectorAll(`[data-heart="${id}"]`).forEach(b=>{b.classList.toggle('saved',saved.includes(id));b.innerHTML=heartIcon(saved.includes(id));b.setAttribute('aria-pressed',String(saved.includes(id)));b.setAttribute('aria-label',saved.includes(id)?'Хадгалснаас хасах':'Хадгалах')});if(location.hash.includes('favorites')&&favTab===1)render();toast(saved.includes(id)?'Сонирхсон жагсаалтад хадгаллаа':'Жагсаалтаас хаслаа')}
function card(h){return `<article class="card" tabindex="0" role="button" aria-label="${esc(h.name)}" onclick="detail(${h.id})" onkeydown="if(event.key==='Enter'&&event.target===this)detail(${h.id})"><div class="photo"><img src="${imageFor(h)}" alt="Гэрэл сайтай орон сууцны дотор тал" loading="lazy"></div><button class="heart ${saved.includes(h.id)?'saved':''}" data-heart="${h.id}" aria-pressed="${saved.includes(h.id)}" aria-label="Хадгалах" onclick="save(${h.id},event)">${heartIcon(saved.includes(h.id))}</button><div><div class="type">${types[h.type]} · ${esc(h.name)}</div><h3>${propertyPriceMarkup(h)}</h3><p>${listingFloorText(h)} · ${h.size} м² · СӨХ <span class="money-amount">${listingFeeText(h)}</span></p><p>${esc(h.desc)}</p><button class="card-building-link" onclick="event.stopPropagation();goFlow('complex/${buildingNames().indexOf(h.name)}')">Хотхоны мэдээлэл ↗</button>${brokerListingBadge(h)}${adminPromotionBadge(h)}${!h.local&&h.id%3===0?'<span class="badge">Эзэмшигч баталгаажуулсан</span>':''}</div></article>`}
function searchbar(){return connectedSearchbar()}
function search(e){e.preventDefault();query=new FormData(e.target).get('query').trim();if(homes.some(h=>String(h.id)===query)){detail(Number(query));return}if(location.hash.startsWith('#/map'))render();else location.hash='/map'}
const homeCategoryLabels=types;
function home(){return `<section class="hero"><div class="hero-inner"><div class="eyebrow">ӨӨРИЙН ОРОН ЗАЙГАА ОЛООРОЙ</div><h1>Таны дараагийн орон зай энд байна</h1>${searchbar()}<div class="category-grid">${types.map((t,i)=>`<a class="category" href="#/map/${i}"><h2>${homeCategoryLabels[i]} ${i===1?'<small>ШИНЭ</small>':''}</h2><p>${['Бүх төрлийн түрээсийн зарыг нэг дороос!','Хотхоны мэдээлэл, бодит хэлцлийн үнэ','Түрээсээс худалдан авалт хүртэл','Тав тухтай, орчин үеийн амьдрал','Өдрөөр / Долоо хоногоор / Сарын түрээс'][i]}</p><div class="building" aria-hidden="true">${categoryIcon(i)}</div></a>`).join('')}</div></div></section>${mobileHomeExtras()}${adminPromotedSection()}<section class="wrap"><div class="section-head"><h2><em>Сүхбаатар</em> орчимд танд санал болгох зарууд ${icon('search')}</h2><button class="recommendation-button" onclick="recommendationModal()">${icon('sparkles')}<span>Нөхцөлөөр санал авах</span></button></div><div class="chips">${['#Эрэлттэй','#Ганцаараа амьдрах','#Худалдах','#Террастай','#Богино хугацаа','#Шинэ зар'].map((t,i)=>`<button class="chip ${activeTag===i?'active':''}" onclick="tag(${i})">${t}</button>`).join('')}</div><div class="recommend"><h3>${icon('trophy')} ${['Энэ өдрүүдийн хамгийн сонирхолтой зарууд','Таны хувийн, тухтай орон зай','Худалдах байрны сонголтууд','Террастай байрны сонголт','Түр нүүхэд тохиромжтой байр','Саяхан нэмэгдсэн зарууд'][activeTag]}</h3><div class="cards">${recommendationHomes().slice(0,8).map(card).join('')}</div><a class="mobile-map-more" href="#/map">${icon('map')}Газрын зураг дээр илүү олон зар харах</a></div><div class="neighborhood"><div><h2>Хорооллоо нэг дороос таньж мэдээрэй</h2><p>Хэрэгтэй мэдээлэл, хөршүүдийн өдөр тутмын түүх</p></div><a href="#/community"><button>Хороолол үзэх →</button></a></div></section><section class="wrap"><div class="section-head"><h2>Шинэ төслийн мэдээлэл</h2><a href="#/sale">Бүгдийг үзэх →</a></div><a class="banner" href="#/sale"><img src="${img(4)}" alt="Шинэ орон сууцны төсөл"><div><span class="badge">БҮРТГЭЛ ЯВАГДАЖ БАЙНА</span><h1>Centerville · Шинэ эхлэл</h1><p>Гвангё · Сувон · 84 м²</p><h2>${formatMnt(320000000)}-өөс</h2><p>600 айл · 2029 онд ашиглалтад</p></div></a></section><section class="wrap"><div class="section-head"><h2>Танд зориулсан мэдээлэл</h2></div><div class="content-grid">${['Солонгост гэрээ олох хялбар боллоо','Нүүхээс өмнө шалгах 7 зүйл','Түрээсийн зах зээлийн мэдээ'].map((t,i)=>`<a class="editorial" href="#/article/${i}"><div class="eyebrow">ӨРӨӨ JOURNAL · 0${i+1}</div><h3>${t}</h3><p>Дэлгэрэнгүй унших →</p></a>`).join('')}</div></section>`}
function tag(i){activeTag=i;const y=scrollY;render();scrollTo(0,y)}
function filtered(){return filteredMongolianHomes()}
function mapPage(){const a=filtered();return `<div class="map-search">${mobileMapCategoryMarkup()}${searchbar()}</div><div class="filters">${types.map((t,i)=>`<button class="${category===i?'active':''}" onclick="chooseMapCategory(${i})">${categoryIcon(i)}<span>${t}</span></button>`).join('')}<button onclick="nhFromPropertyMap()">${icon('users')}<span>Манай хороолол</span></button></div><div class="filters"><button class="${filter.locations?.length?'active':''}" onclick="filterModal('location')">${icon('pin')}<span>${esc(locationFilterLabel())}</span>${icon('chevron-down')}</button><button class="${filter.deal!=='all'||filter.minRent>0||filter.max>0||filter.minDeposit>0||filter.maxDeposit>0||filter.includeFee?'active':''}" onclick="filterModal('price')">${icon('wallet')}<span>Үнэ, ₮</span>${icon('chevron-down')}</button><button class="${filter.rooms?.length?'active':''}" onclick="filterModal('rooms')">${icon('house')}<span>Өрөө</span>${icon('chevron-down')}</button><button class="${filter.minSize||filter.maxSize?'active':''}" onclick="filterModal('size')">${icon('ruler')}<span>Талбай</span>${icon('chevron-down')}</button><button class="${filter.year?'active':''}" onclick="filterModal('year')">${icon('calendar')}<span>Ашиглалтад орсон он</span>${icon('chevron-down')}</button><button class="${filter.floor||filter.maxFloor?'active':''}" onclick="filterModal('floor')">${icon('stairs')}<span>Давхар</span>${icon('chevron-down')}</button><button class="${filter.garage&&filter.garage!=='all'?'active':''}" onclick="filterModal('garage')">${icon('garage')}<span>Гараж</span>${icon('chevron-down')}</button><button class="${filter.parking||filter.elevator||filter.pet||filter.balcony||filter.furnished?'active':''}" onclick="filterModal('more')">${icon('sliders')}<span>Нэмэлт шүүлтүүр</span>${icon('chevron-down')}</button><button onclick="resetFilters()" aria-label="Шүүлтүүр цэвэрлэх" title="Шүүлтүүр цэвэрлэх">${icon('refresh')}</button></div><div class="map-layout"><aside class="listing"><div class="list-head"><b>Зарууд · ${a.length}</b><button class="save-search-button" onclick="saveCurrentSearch()">${icon('bookmark')}<span>Хайлт</span></button><div class="sort-control">${icon('sort')}<select aria-label="Эрэмбэлэх" onchange="sort=this.value;render()">${sortOptionsMarkup()}</select></div></div>${a.length?a.map(card).join(''):'<div class="empty"><b>Зар олдсонгүй</b>Хайлт, шүүлтүүрээ өөрчилнө үү.<p><button onclick="query=\'\';resetFilters()">Хайлт цэвэрлэх</button></p></div>'}</aside>${propertyMapMarkup()}${mobileMapControlsMarkup()}</div>`}function mapZoom(d){zoom=Math.max(.6,Math.min(2.5,zoom+d));$('.map').style.setProperty('--zoom',zoom);toast(`Масштаб ${Math.round(zoom*100)}%`)}
function resetFilters(){filter=defaultFilter();render()}
function modal(body){destroyListingSavedMap();document.body.style.overflow='hidden';$('#overlay').innerHTML=`<div class="shade" onclick="closeOverlay()"></div><section class="modal" role="dialog" aria-modal="true"><button class="close" aria-label="Хаах" onclick="closeOverlay()">${icon('close')}</button>${body}</section>`;$('.modal button.close').focus()}
function closeOverlay(){destroyListingSavedMap();$('#overlay').innerHTML='';document.body.style.overflow=''}
function filterModal(kind){openConnectedFilters(kind)}
function applyFilter(e,k){e.preventDefault();const f=new FormData(e.target);for(const [key,v] of f)filter[key]=key==='deal'?v:key==='parking'||key==='elevator'||key==='pet'?true:Number(v);if(k==='more')for(const key of ['parking','elevator','pet'])filter[key]=f.has(key);closeOverlay();render()}
let activeDetail=null;
function closeDetail(){if(isMobileView()&&location.hash.startsWith('#/room/')){mobileBack();return}activeDetail=null;document.querySelector(".detail-column")?.remove();document.querySelector(".map-layout")?.classList.remove("with-detail");document.querySelectorAll(".card.selected").forEach(el=>el.classList.remove("selected"))}
function detail(id){const h=homes.find(h=>h.id===id);if(!h||!isPublicListing(h)){toast('Зар нийтэд харагдахгүй байна.');return}proTrackView(id);if(isMobileView()){if(location.hash!=='#/room/'+id){if(!location.hash.startsWith('#/room/'))mobileDetailReturn=location.hash||'#/';activeDetail=null;location.hash='/room/'+id}else mountMobileProperty(id);return}activeDetail=id;if(!location.hash.startsWith('#/map')){category=h.type;query='';filter=defaultFilter();location.hash='/map/'+h.type;return}recent=[id,...recent.filter(n=>n!==id)].slice(0,50);localStorage.setItem('mn-recent',JSON.stringify(recent));const detailMarkup=listingDetailMarkup(h);document.querySelector('.detail-column')?.remove();const layout=document.querySelector('.map-layout');layout.classList.add('with-detail');const column=document.createElement('aside');column.className='detail-column';column.innerHTML=detailMarkup;column.append(column.querySelector('.detail-actions'));bindDetailNavigation(column);layout.insertBefore(column,layout.querySelector('.map'));document.querySelectorAll('.listing .card').forEach(el=>el.classList.toggle('selected',el.getAttribute('onclick')===`detail(${id})`))}
function gallery(id,index){connectedGallery(id,index)}
function nearby(tab){openNearbyFlow(tab)}
