function sale(){return `<div class="wrap"><h1 class="page-title">Шинэ төслүүд</h1><div class="subnav">${['Төслийн мэдээлэл','Сэдэвчилсэн төсөл','Хуваарь','Гарын авлага','Брэнд'].map((t,i)=>`<button class="${saleTab===i?'active':''}" onclick="saleTab=${i};render()">${t}</button>`).join('')}</div>${saleTab===2?calendar():saleTab===3?guide():saleTab===4?`<div class="content-grid">${['e-Pyeonhansesang','SK VIEW','IPARK','Xi','Prugio'].map(t=>`<div class="editorial" onclick="project('${t}')"><div class="eyebrow">BRAND COLLECTION</div><h3>${t}</h3><p>Төслүүдийг харах →</p></div>`).join('')}</div>`:saleTab===1?`<div class="content-grid">${['Одоо бүртгэл авч буй','Чөлөөт сонголттой','Премиум хотхонууд'].map((t,i)=>`<div class="editorial" onclick="project('${t}')"><div class="eyebrow">THEME 0${i+1}</div><h3>${t}</h3><p>Шинэ орон зайгаа нээгээрэй →</p></div>`).join('')}</div>`:`<div class="banner"><img src="${img(4)}" alt="Орон сууцны төсөл"><div><span class="badge">ЖИШЭЭ · БҮРТГЭЛ НЭЭЛТТЭЙ</span><h1>Гвангё Centerville</h1><p>Сувон · 84 м² · 600 айл</p><h2>${formatMnt(320000000)}-өөс</h2><button class="primary" onclick="project(projects[0])">Дэлгэрэнгүй →</button></div></div><h2>Төслийн мэдээлэл</h2><table class="table"><thead><tr><th>Төлөв</th><th>Төсөл / Байршил</th><th>Үнэ, ₮</th><th>Айл</th><th>Талбай</th></tr></thead><tbody>${projects.map((p,i)=>`<tr><td><span class="badge">${i%2?'Төлөвлөсөн':'Бүртгэлтэй'}</span></td><td><a href="#" onclick="event.preventDefault();project('${p}')"><b>${p}</b><p>${areas[i]} · Жишээ төсөл</p></a></td><td>${formatMnt([320000000,250000000,180000000,450000000,380000000][i])}-өөс</td><td>${[360,866,400,1,2][i]}</td><td>59 – 84 м²</td></tr>`).join('')}</tbody></table><div class="neighborhood"><div><h2>Төслийн хуваариа шалгаарай</h2><p>Бүртгэл, зарлал, гэрээний үе шат</p></div><button onclick="saleTab=2;render()">Хуваарь →</button></div>`}</div>`}
function calendar(){return `<div class="section-head"><h2>2026 оны 11 сар</h2><span class="badge">Жишээ хуваарь</span></div><div class="calendar">${['Да','Мя','Лх','Пү','Ба','Бя','Ня'].map(t=>`<div class="day" style="min-height:40px;background:#fafafa">${t}</div>`).join('')}${Array.from({length:30},(_,i)=>`<div class="day">${i+1}${i%3===0?`<br><button class="badge" onclick="project('${projects[i%5]}')">${i%2?'Гэрээ':'Бүртгэл'} · ${i%5+1}</button>`:''}</div>`).join('')}</div>`}
