const faqs=[['Хэрхэн байр хайх вэ?','Дүүрэг, хотхон эсвэл зарын дугаараар хайж, үнэ болон нэмэлт нөхцөлөөр шүүнэ.'],['Хадгалсан зарыг хаанаас үзэх вэ?','Сонирхсон жагсаалтаас зар, хотхон, хадгалсан хайлтаа харна.'],['Зар хэрхэн нэмэх вэ?','Зар нэмэх цэсний 4 алхмыг бөглөнө. Демо зар зөвхөн энэ браузерт хадгалагдана.'],['Зарын үнэ ямар нэгжтэй вэ?','Жишээ үнийг төгрөгөөр (₮) илэрхийлнэ. Бодит зах зээлийн ханш эсвэл валютын хөрвүүлэлт биш.'],['Бүртгэл болон хүсэлт бодит уу?','Үгүй. Бүртгэл, код шалгалт, хүсэлтүүд нь локал демо. Нууц үг, имэйл хадгалагдахгүй, SMS илгээгдэхгүй.']];
function faqItems(){return faqs.map(([q,a])=>`<details class="accordion"><summary>${q}</summary><p>${a}</p></details>`).join('')}
function infoPage(route){if(route==='faq')return `<div class="wrap"><h1 class="page-title">Түгээмэл асуулт</h1>${faqItems()}</div>`;if(route==='agent')return `<div class="wrap"><div class="banner"><div><div class="eyebrow">ӨРӨӨ PRO</div><h1>Таны зарыг зөв хүнд хүргэнэ.</h1><p>Үл хөдлөх хөрөнгийн агентуудад зориулсан үйлчилгээ</p><button class="primary" onclick="location.hash='/inquiry'">Зар сурталчилгааны лавлагаа</button></div><img src="${img(0)}" alt="Агентын үйлчилгээ"></div><div class="content-grid">${['Багц үйлчилгээ','Ердийн зар','Премиум зар'].map(t=>`<div class="editorial"><h3>${t}</h3><p>Зарын харагдах байдал, хотхон болон бүсээр байршуулалт.</p><button onclick="location.hash='/inquiry'">Лавлах →</button></div>`).join('')}</div><h2>Агентын бусад зар · Жишээ</h2><div class="cards">${homes.slice(0,4).map(card).join('')}</div></div>`;if(route==='inquiry')return `<div class="wrap" style="max-width:700px"><h1 class="page-title">Холбоо барих</h1><p class="notice">Демо маягт. Хүсэлт сервер рүү илгээгдэхгүй.</p><form onsubmit="event.preventDefault();this.reset();toast('Туршилтын маягт шалгагдлаа. Хүсэлт илгээгдээгүй.')"><label class="field">Ангилал<select><option>Үйлчилгээний асуулт</option><option>Зар сурталчилгаа</option><option>Агентын бүртгэл</option></select></label><label class="field">Имэйл<input required type="email" placeholder="example@example.com"></label><label class="field">Асуулт<textarea required></textarea></label><button class="primary">Маягт шалгах</button></form></div>`;if(route==='notice')return `<div class="wrap"><h1 class="page-title">Мэдээ, мэдээлэл</h1>${[['Монгол хэл дээрх хувилбарт тавтай морил!','Хайлт, газрын зураг, хадгалсан зарууд болон дэлгэрэнгүй мэдээллийг туршиж үзээрэй.'],['Хуурамч зараас сэрэмжлээрэй','Төлбөр хийхээс өмнө байрыг үзэж, агент болон бичиг баримтыг шалгана уу.']].map(([t,p])=>`<details class="accordion"><summary>${t} <span class="badge">2026.11.09</span></summary><p>${p}</p></details>`).join('')}</div>`;if(route==='terms'||route==='privacy')return `<div class="wrap" style="max-width:800px"><h1 class="page-title">${route==='terms'?'Үйлчилгээний нөхцөл':'Нууцлалын мэдээлэл'}</h1><p class="notice">Демо хувилбарын тайлбар · 2026.11.09</p><h2>Туршилтын зориулалт</h2><p>Энэ сайт нь Монгол хэл дээрх интерфэйсийн загвар. Бодит үл хөдлөх хөрөнгийн зуучлал, гэрээ, төлбөрийн үйлчилгээ үзүүлэхгүй.</p><h2>Хадгалагдах мэдээлэл</h2><p>Хадгалсан болон сүүлд үзсэн зарын дугаарыг таны браузерын localStorage-д хадгална. Зар, лавлагаа, мэдээлсэн зар, нийтлэл болон дэлгэцийн нэр энэ браузерт хадгалагдана. Нууц үг, нэвтрэх имэйл хадгалахгүй. PRO-д оруулсан харилцагчийн холбоо барих мэдээлэл, тэмдэглэл, хуваарь болон байгууллагын мэдээлэл энэ браузерт хадгалагдана, серверт илгээгдэхгүй. ADMIN шийдвэр, хариу, мэдээ болон үйлдлийн түүх мөн энэ браузерт хадгалагдана. Жишээ зургийг Unsplash-аас ачаална.</p><button onclick="clearDemoData()">Демогийн хадгалсан мэдээлэл цэвэрлэх</button></div>`;return `<div class="wrap"><div class="eyebrow">ӨРӨӨ ПЛАТФОРМ</div><h1 class="page-title">Гэрээ олох аялал илүү ойлгомжтой.</h1><p style="max-width:700px;line-height:2">Өрөө платформ нь Монголд орон сууц, хаус, оффис, газар болон түрээсийн орон зай хайх, зарлахад тусална. Байршил, төгрөгөөр илэрхийлсэн үнэ, хорооллын мэдээлэл болон зуучлалын байгууллагуудыг нэг дороос хараарай. Одоогийн хувилбар нь локал демо; бодит нэвтрэлт, гэрээ, төлбөр болон DAN баталгаажуулалт хараахан холбогдоогүй.</p><a href="#/map"><button class="primary">Байр хайж эхлэх →</button></a></div>`}
function article(i){return `<div class="wrap" style="max-width:850px"><div class="eyebrow">ӨРӨӨ JOURNAL · ГАРЫН АВЛАГА</div><h1 class="page-title">${['Солонгост гэрээ олох хялбар боллоо','Нүүхээс өмнө шалгах 7 зүйл','Түрээсийн зах зээлийн мэдээлэл'][i%3]}</h1><img style="width:100%;border-radius:12px;max-height:390px;object-fit:cover" src="${img(i)}" alt="Тав тухтай орон сууц"><p class="notice">Танилцуулгын жишээ нийтлэл. Бодит зах зээлийн тайлан биш.</p>${faqItems()}<p><a href="#/map"><button class="primary">Зарууд үзэх</button></a></p></div>`}
function render(){destroyListingEditorMap();destroyPropertyMap();destroyOfficeMap();destroyNeighborhoodMap();const r=(location.hash||'#/').slice(2).split('/');const route=r[0];if(route==='map'&&r[1]!==undefined)category=Number(r[1]);document.body.classList.toggle('map-page',route==='map');document.body.classList.toggle('pro-page',route==='pro');document.body.classList.toggle('admin-page',route==='admin');if(route==='map'&&activeDetail&&!filtered().some(h=>h.id===activeDetail))activeDetail=null;const flowContent=flowRoute(r);$('#app').innerHTML=flowContent??(route==='map'?mapPage():route==='favorites'?favorites():route==='sale'?sale():route==='login'?login():route==='community'?community():route==='article'?article(Number(r[1])||0):route==='room'?(isMobileView()?mobilePropertyPage(Number(r[1])):home()):route?infoPage(route):home());refreshAccount();mountHeaderIcons();mountMobileApp(route);if(route==='community')decorateCommunity();document.querySelector('nav').classList.remove('open');if(route==='room')detail(Number(r[1]));else if(route==='map'&&activeDetail)detail(activeDetail);else if(route!=='map')activeDetail=null;if(route==='map')initializePropertyMap();if(route==='offices')mountOfficePage(r[1]);if(route==='community')mountNeighborhoodMap();mountListingLocation();document.title=route==='community'?'Манай хороолол · '+nhScopeLabel()+' · Өрөө':route==='offices'?(officePublicModel(r[1])?.name||'Зуучлалын байгууллагууд')+' · Өрөө':route==='admin'?adminTitle(r[1])+' · Өрөө ADMIN':route==='pro'?((PRO_MENU.find(m=>m[0]===r[1])?.[2]||(r[1]==='new'?'Зар нэмэх':'Ажлын самбар'))+' · Өрөө PRO'):(route==='map'?'Газрын зураг':route==='favorites'?'Сонирхсон':route==='sale'?'Шинэ төсөл':'Өөрийн орон зайгаа олоорой')+' · Өрөө платформ'}
window.addEventListener('hashchange',()=>{closeOverlay();render();scrollTo(0,0)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#overlay').innerHTML)closeOverlay();else closeDetail()}});hydrateLocalListings();localizeListingData();connectGlobalFlowEvents();render();
